import org.springframework.web.util.pattern.PathPatternParser;
import org.springframework.web.util.pattern.PathPattern;
public class PP {
  public static void main(String[] a) {
    String[] pats = {"/{*path:[^\\.]*}", "/{path:[^\\.]*}/{*rest}", "/{path:^(?!api).*}/**", "/**/{path:[^\\.]*}", "/{path:[^\\.]*}"};
    String[] paths = {"/foo.js","/foo/bar.js","/admin/user-management","/non-existant-mapping","/a/b/c/d.js"};
    for (String p : pats) {
      try {
        PathPattern pp = PathPatternParser.defaultInstance.parse(p);
        StringBuilder sb = new StringBuilder(p + " => ");
        for (String s : paths) sb.append(s).append('=').append(pp.matches(org.springframework.http.server.PathContainer.parsePath(s))).append(' ');
        System.out.println(sb);
      } catch (Exception e) { System.out.println(p + " => ERROR " + e.getMessage()); }
    }
  }
}
EOF
