package io.github.jhipster.sample.web.rest;

import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.GetMapping;

@Controller
public class ClientForwardController {

    /**
     * Forwards any unmapped paths (except those containing a period) to the client {@code index.html}.
     * <p>
     * Spring 6 parses request mappings with {@code PathPattern} by default, which does not allow a {@code **} followed by
     * more path segments, so the Ant-style {@code /**}{@code /{path:[^\\.]*}} pattern is expressed as one pattern per depth.
     * Depths 1 to 6 cover all client routes of the application.
     * @return forward to client {@code index.html}.
     */
    @GetMapping(
        value = {
            "/{p1:[^\\.]+}",
            "/{p1:[^\\.]+}/{p2:[^\\.]+}",
            "/{p1:[^\\.]+}/{p2:[^\\.]+}/{p3:[^\\.]+}",
            "/{p1:[^\\.]+}/{p2:[^\\.]+}/{p3:[^\\.]+}/{p4:[^\\.]+}",
            "/{p1:[^\\.]+}/{p2:[^\\.]+}/{p3:[^\\.]+}/{p4:[^\\.]+}/{p5:[^\\.]+}",
            "/{p1:[^\\.]+}/{p2:[^\\.]+}/{p3:[^\\.]+}/{p4:[^\\.]+}/{p5:[^\\.]+}/{p6:[^\\.]+}",
        }
    )
    public String forward() {
        return "forward:/";
    }
}
